(* [comment removed for export] *)
Inductive zexp : Type := ZL (z : Z) | ZA (j : nat) | ZAdd (a b : zexp) | ZSub (a b : zexp) | ZMul (a b : zexp).

Fixpoint zx (z : zexp) : expr :=
  match z with
  | ZL c => ELit c | ZA j => EVar j
  | ZAdd a b => EAlu ALU_ADD (zx a) (zx b) | ZSub a b => EAlu ALU_SUB (zx a) (zx b) | ZMul a b => EMd M_MUL (zx a) (zx b)
  end.

Fixpoint zden (zv : list Z) (z : zexp) : Z :=
  match z with
  | ZL c => c | ZA j => nth j zv 0%Z
  | ZAdd a b => (zden zv a + zden zv b)%Z | ZSub a b => (zden zv a - zden zv b)%Z | ZMul a b => (zden zv a * zden zv b)%Z
  end.

Fixpoint zatoms_lt (b : nat) (z : zexp) : bool :=
  match z with
  | ZL _ => true | ZA j => Nat.ltb j b
  | ZAdd a c | ZSub a c | ZMul a c => zatoms_lt b a && zatoms_lt b c
  end.

