(* [comment removed for export] *)
Definition kx_env (ws xs : list word) : env := Env (fun n => nth n (ws ++ xs) (Z_to_bv 64 0)) (fun _ => []).

Lemma kx_env_atom : forall ws zv xs, Forall2 (fun w z => w = Z_to_bv 64 z) ws zv ->
  forall j, (j < length zv)%nat -> ev (kx_env ws xs) j = Z_to_bv 64 (nth j zv 0%Z).
Proof.
