(* [comment removed for export] *)
Definition rdval (segs : list Segment) (m : word -> option byte) (a : word) (n : nat) (sx : bool) : word :=
  match rdn segs m a n with
  | Some bs => Z_to_bv 64 (extz sx n (bytes_le_to_Z bs))
  | None => Z_to_bv 64 0
  end.

(* [comment removed for export] *)
Fixpoint expr_vars_lt (b : nat) (e : expr) : bool :=
  match e with
  | ELit _ => true
  | EVar n => Nat.ltb n b
  | EAlu _ x y | EAluw _ x y | EMd _ x y | EMdw _ x y => expr_vars_lt b x && expr_vars_lt b y
  | EExt _ _ _ x => expr_vars_lt b x
  | EBlob _ _ _ _ => true
  end.

Lemma edenot_agree : forall b E E' e,
  (forall n, (n < b)%nat -> ev E n = ev E' n) -> eb E = eb E' -> expr_vars_lt b e = true -> edenot E e = edenot E' e.
Proof.
