(* [comment removed for export] *)
Fixpoint kx_vals_go (segs : list Segment) (m : word -> option byte) (ws : list word)
         (reads : list (saddr * nat * bool)) (acc : list word) : list word :=
  match reads with
  | [] => acc
  | (a, n, sx) :: rest => kx_vals_go segs m ws rest (acc ++ [rdval segs m (adenot (kx_env ws acc) a) n sx])
  end.
Definition kx_vals segs m ws reads : list word := kx_vals_go segs m ws reads [].

Fixpoint reads_scoped (b : nat) (reads : list (saddr * nat * bool)) : bool :=
  match reads with
  | [] => true
  | (a, _, _) :: rest => expr_vars_lt b (a_base a) && reads_scoped (S b) rest
  end.

Lemma kx_vals_go_prefix : forall segs m ws reads acc k, (k < length acc)%nat ->
  nth k (kx_vals_go segs m ws reads acc) (Z_to_bv 64 0) = nth k acc (Z_to_bv 64 0).
Proof.
